// Split the fetched threads into items and keep only the ones DUE for a nudge.
// 24h-window-safe: updated_at (last real conversation turn) must be < 23h old.
// Cap: max 2 nudges; spacing: 1st after 1h quiet, 2nd after 6h. Skip booked leads.
let rows = $input.all().map(i => i.json);
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
const now = Date.now();
const out = [];
for (const t of rows) {
  if (!t || !t.psid) continue;
  const info = (t.info && typeof t.info === 'object') ? t.info : {};
  if (info.preferred_datetime) continue;                 // already booked → skip
  const sent = info.followups_sent || 0;
  if (sent >= 2) continue;                                // cap reached
  const updatedAt = new Date(t.updated_at).getTime();
  if (!(updatedAt > 0)) continue;
  const hoursSinceConvo = (now - updatedAt) / 3600000;
  if (hoursSinceConvo >= 23) continue;                    // outside 24h window
  const lastActivity = info.last_followup_at ? new Date(info.last_followup_at).getTime() : updatedAt;
  const minsSince = (now - lastActivity) / 60000;
  const need = sent === 0 ? 60 : 360;                     // 1h then 6h
  if (minsSince < need) continue;                         // not quiet enough yet

  const history = Array.isArray(t.history) ? t.history : [];
  const attempt = sent + 1;
  const sys = [
    'You are "Vertex Assistant" on the Facebook Page of Vertex AI Marketing (we build landing page funnels, lead capture, FB Messenger integration, FB ads, and booking + email follow-up automation for PH SMBs).',
    'PACKAGES (quote exactly if relevant): BASIC \u20b15,000, STANDARD \u20b16,990, PREMIUM \u20b110,000. All include FB Messenger integration + 1 Year Free Domain.',
    'This customer went QUIET and has not replied. Write ONE short, warm Taglish follow-up nudge (this is follow-up #' + attempt + ') to gently re-engage them:',
    '- reference the conversation so far, add a little value or a soft reason to continue, and end with an easy question toward booking a FREE call/demo.',
    '- persuade with TRUTH (value over price, gentle urgency), never pushy, never repeat yourself, no fake scarcity or invented stats.',
    'Keep it 1-2 lines, few tasteful emojis.',
    'Output ONLY a valid JSON object, nothing else: {"reply": "<your Taglish message>"}'
  ].join('\n');

  const messages = [{ role: 'system', content: sys }, ...history.slice(-10)];
  out.push({ json: {
    psid: String(t.psid),
    name: t.name || '',
    info,
    history,
    attempt,
    openaiBody: { model: 'gpt-4o-mini', messages, max_tokens: 220, response_format: { type: 'json_object' } }
  }});
}
return out;

// Parse the model reply and prepare the FB send + thread update.
const src = $('Select Due').item.json;
let reply = '';
try { const p = JSON.parse($json.choices[0].message.content); reply = (p.reply || '').toString().trim(); } catch (e) { reply = ''; }
if (!reply) { return []; } // nothing to send
const info = Object.assign({}, src.info || {});
info.followups_sent = (info.followups_sent || 0) + 1;
info.last_followup_at = new Date().toISOString();
const newHistory = [...(src.history || []), { role: 'assistant', content: reply }].slice(-16);
return [{ json: { psid: src.psid, reply, info, newHistory } }];
